test('loading is true immediately', () => {
  global.fetch = vi.fn(() => new Promise(() => {}));
  const { result } = renderHook(() => useFetchSimple('/api/test'));
  expect(result.current.loading).toBe(true);
});

test('populates data on successful fetch', async () => {
  global.fetch = vi.fn(() =>
    Promise.resolve({ ok: true, json: () => Promise.resolve({ id: 1 }) } as Response)
  );
  const { result } = renderHook(() => useFetchSimple('/api/test'));
  await act(async () => {});
  expect(result.current.loading).toBe(false);
  expect(result.current.data).toEqual({ id: 1 });
});

test('sets error when fetch rejects', async () => {
  global.fetch = vi.fn(() => Promise.reject(new Error('network error')));
  const { result } = renderHook(() => useFetchSimple('/api/fail'));
  await act(async () => {});
  expect(result.current.error).toBeInstanceOf(Error);
  expect(result.current.loading).toBe(false);
});

